#!/usr/bin/env python3
"""Fail-closed commit metadata and tracked-path hygiene check for pushed ranges."""
from __future__ import annotations

import os
import re
import subprocess
import sys


BAD_MARKERS = (
    "co-authored-by", "claude", "anthropic", "codex", "openai", "chatgpt",
    "gpt-", "generated with", "generated by",
)
EXPECTED_NAME = "Connor Avila"
MAX_RANGE_COMMITS = 10_000
PATH_SCAN_CHUNK = 128


class Refusal(Exception):
    def __init__(self, rule: str, sha: str | None = None):
        self.rule = rule
        self.sha = short_sha(sha) or event_head_sha() or "000000000000"


def short_sha(value: str | None) -> str | None:
    if value is not None and re.fullmatch(r"[0-9a-fA-F]{7,64}", value):
        return value[:12].lower()
    return None


def event_head_sha() -> str | None:
    if os.environ.get("GITHUB_EVENT_NAME") == "pull_request":
        candidate = os.environ.get("PR_HEAD_SHA", "")
    else:
        candidate = os.environ.get("GITHUB_SHA", "")
    if re.fullmatch(r"[0-9a-fA-F]{40}|[0-9a-fA-F]{64}", candidate):
        return candidate[:12].lower()
    return None


def failure_line(refusal: Refusal) -> str:
    return f"commit_hygiene_failed sha={refusal.sha} rule={refusal.rule}"


def git(*args: str, check: bool = True, cwd=None) -> bytes:
    result = subprocess.run(["git", *args], cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    if check and result.returncode:
        raise Refusal("invalid-range")
    return result.stdout


def is_commit(ref: str, cwd=None) -> bool:
    return bool(ref) and subprocess.run(
        ["git", "cat-file", "-e", f"{ref}^{{commit}}"],
        cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    ).returncode == 0


def commit_ids(base: str, head: str, require_ancestor: bool, cwd=None) -> list[str]:
    if not is_commit(base, cwd) or not is_commit(head, cwd):
        raise Refusal("invalid-range")
    common = subprocess.run(["git", "merge-base", base, head],
                            cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    if common.returncode or not common.stdout.strip():
        raise Refusal("unrelated-range")
    if require_ancestor and subprocess.run(
        ["git", "merge-base", "--is-ancestor", base, head],
        cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    ).returncode:
        raise Refusal("non-ancestor-range")
    ids = git("rev-list", "--max-count", str(MAX_RANGE_COMMITS + 1), "--reverse",
              f"{base}..{head}", cwd=cwd).decode("ascii").splitlines()
    if not ids:
        raise Refusal("empty-range")
    if len(ids) > MAX_RANGE_COMMITS:
        raise Refusal("range-too-large")
    return ids


def check_commit(sha: str, expected_email: str, cwd=None) -> None:
    raw = git("show", "-s", "--format=%an%x00%ae%x00%cn%x00%ce%x00%B", sha, cwd=cwd)
    fields = raw.split(b"\0", 4)
    if len(fields) != 5:
        raise Refusal("metadata-unreadable", sha)
    author_name, author_email, committer_name, committer_email, message = fields
    if author_name.decode("utf-8", "replace") != EXPECTED_NAME:
        raise Refusal("author-name", sha)
    if committer_name.decode("utf-8", "replace") != EXPECTED_NAME:
        raise Refusal("committer-name", sha)
    if author_email.decode("utf-8", "replace") != expected_email:
        raise Refusal("author-email", sha)
    if committer_email.decode("utf-8", "replace") != expected_email:
        raise Refusal("committer-email", sha)
    lowered = message.decode("utf-8", "replace").lower()
    if any(marker in lowered for marker in BAD_MARKERS):
        raise Refusal("prohibited-message-marker", sha)


def check_tracked_paths(commits: list[str], cwd=None) -> None:
    # Compose the user-specific path fragment so this checker does not contain the literal.
    needle = "/" + "home" + "/" + "connoravila"
    for start in range(0, len(commits), PATH_SCAN_CHUNK):
        result = subprocess.run(
            ["git", "grep", "-l", "--fixed-strings", needle,
             *commits[start:start + PATH_SCAN_CHUNK], "--", ".", ":(exclude)docs/archive/**"],
            cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
        )
        if result.returncode not in (0, 1):
            raise Refusal("tracked-path-scan")
        if result.returncode == 0:
            for sha in commits[start:start + PATH_SCAN_CHUNK]:
                individual = subprocess.run(
                    ["git", "grep", "-l", "--fixed-strings", needle, sha, "--", ".",
                     ":(exclude)docs/archive/**"],
                    cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                )
                if individual.returncode == 0:
                    raise Refusal("tracked-user-path", sha)
                if individual.returncode != 1:
                    raise Refusal("tracked-path-scan", sha)
            raise Refusal("tracked-path-scan")


def main() -> int:
    expected = os.environ.get("EXPECTED_COMMIT_EMAIL", "")
    if not expected or "\n" in expected or "\r" in expected:
        raise Refusal("missing-or-invalid-email-variable")
    event = os.environ.get("GITHUB_EVENT_NAME", "")
    ref = os.environ.get("GITHUB_REF", "")
    if event == "pull_request":
        base, head = os.environ.get("PR_BASE_SHA", ""), os.environ.get("PR_HEAD_SHA", "")
        require_ancestor = False
    elif event == "push" and ref.startswith("refs/heads/train/"):
        base, head = "refs/remotes/origin/main", os.environ.get("GITHUB_SHA", "")
        require_ancestor = True
    elif event == "push" and ref == "refs/heads/main":
        base, head = os.environ.get("PUSH_BEFORE_SHA", ""), os.environ.get("GITHUB_SHA", "")
        require_ancestor = True
    else:
        raise Refusal("unsupported-event-range")
    ids = commit_ids(base, head, require_ancestor)
    for sha in ids:
        check_commit(sha, expected)
    check_tracked_paths(ids)
    return 0


if __name__ == "__main__":
    try:
        result = main()
    except Refusal as refusal:
        print(failure_line(refusal), file=sys.stderr)
        raise SystemExit(1)
    except Exception:
        print(failure_line(Refusal("checker-error")), file=sys.stderr)
        raise SystemExit(1)
    raise SystemExit(result)
